// Read-only HTTP smoke for an actual LauncherArmory account cache.
// Usage: node verify-real-friend-assets.cjs <account-cache-directory> <report.json> [character-id]
// No replacement roster, item icons or model manifests are generated by this check.
const fs = require('node:fs/promises');
const path = require('node:path');
const assert = require('node:assert/strict');
const {createHash,randomBytes} = require('node:crypto');
const {createLauncherServer} = require('./launcher-server.cjs');
const {LauncherArmory} = require('./launcher-armory.cjs');
const {modelAssetsAvailable} = require('./launcher-models.cjs');

const pngSignature = Buffer.from('89504e470d0a1a0a','hex');
const digest = bytes => createHash('sha256').update(bytes).digest('hex');
const json = async file => JSON.parse(await fs.readFile(file,'utf8'));

function pngDimensions(bytes,name) {
  assert.ok(bytes.length>24 && bytes.subarray(0,8).equals(pngSignature),`${name}: invalid PNG signature`);
  assert.equal(bytes.toString('ascii',12,16),'IHDR',`${name}: missing PNG image header`);
  const width = bytes.readUInt32BE(16), height = bytes.readUInt32BE(20);
  assert.ok(width>1 && height>1,`${name}: empty or placeholder-sized PNG`);
  return {width,height};
}

async function verify(accountDirectory,reportFile,characterId) {
  const report = {kind:'actual-cache-http-assets',startedAt:new Date().toISOString(),
    scope:'Copied real account cache through the production loopback server and a headless browser at 1598 x 997; native client-path resolution is outside this check.',
    accountDirectory,characters:[],errors:[]};
  let server;
  try {
    const roster = await json(path.join(accountDirectory,'roster.json'));
    assert.equal(roster.schemaVersion,1,'Unsupported account cache schema');
    assert.ok(Number.isInteger(roster.account) && roster.account>0,'Missing account identity');
    assert.ok(Array.isArray(roster.characters) && roster.characters.length,'The real roster must contain characters');
    const states = new Map();
    for (const row of roster.characters) {
      assert.match(row.id,/^[1-9][0-9]{0,9}$/,'Invalid character identity');
      assert.ok(!states.has(row.id),'Duplicate character identity');
      const state = await json(path.join(accountDirectory,row.id+'.json'));
      assert.equal(state.owner,roster.account,'An account cache must not expose another account');
      assert.equal(state.character?.characterId,row.id,'Character identity mismatch');
      assert.equal(state.character?.name,row.name,'Character name mismatch');
      assert.match(state.revision,/^[a-f0-9]{32}$/,'Invalid cached revision');
      states.set(row.id,state);
    }
    const selected = characterId ? roster.characters.filter(row => row.id===characterId) : roster.characters;
    assert.ok(selected.length,'Requested character is absent from this account cache');
    const unavailableProvider = async () => { throw new Error('This cache-only smoke must not request live data'); };
    const armory = new LauncherArmory(roster.account,{source:'rpc'},
      {root:path.dirname(accountDirectory),loadRoster:unavailableProvider,loadCatalog:unavailableProvider});
    // Freeze the validated copied cache without starting refreshes or model exports.
    armory.roster = roster.characters; armory.entries = states; armory.status = 'cached';
    const key = randomBytes(32).toString('hex');
    server = createLauncherServer({key,armory});
    await new Promise((resolve,reject) => { server.once('error',reject); server.listen(0,'127.0.0.1',resolve); });
    const origin = `http://127.0.0.1:${server.address().port}`;
    const get = async (route,withKey=true) => fetch(origin+route,{
      headers:withKey ? {'X-Atlas-Armory-Key':key} : {},signal:AbortSignal.timeout(10000)
    });
    const getJson = async route => {
      const response = await get(route); assert.equal(response.status,200,route);
      assert.match(response.headers.get('content-type'),/^application\/json/);
      return response.json();
    };
    assert.equal((await get('/characters.json',false)).status,403,'Anonymous roster access must stay forbidden');
    assert.deepEqual((await getJson('/characters.json')).characters.map(({available,...row}) => row),roster.characters);
    for (const row of selected) {
      const result = {id:row.id,name:row.name,icons:[],models:[],resources:[],errors:[]};
      report.characters.push(result);
      try {
        const state = states.get(row.id);
        const prefix = `/characters/${row.id}`;
        const manifest = await getJson(prefix+'/armory.json');
        assert.equal(manifest.assetBase,`${prefix}/snapshots/${state.revision}/assets/`);
        assert.equal(manifest.characterId,row.id);
        assert.equal(manifest.modelReady,true,`${row.name}: model is ${manifest.modelStatus}`);
        assert.equal(await modelAssetsAvailable(state.assetDir,state.character),true,`${row.name}: incomplete or obsolete model export`);
        const view = await get(prefix+'/view');
        assert.equal(view.status,200,'The character iframe must be served');
        assert.match(await view.text(),/src="\/app\.js"/,'The iframe must load the current shared viewer');
        assert.deepEqual(await getJson(manifest.assetBase+'character.json'),state.character);
        assert.deepEqual(await getJson(manifest.assetBase+'item-details.json'),state.details);
        assert.equal(state.details.characterCapturedAt,state.character.capturedAt);
        const requests = new Map();
        const resource = async name => {
          assert.match(name,/^[a-zA-Z0-9_-]+\.(png|gltf|bin)$/,'Asset names must remain inside the character snapshot');
          if (requests.has(name)) return requests.get(name);
          const request = (async () => {
            const route = manifest.assetBase+name;
            assert.equal((await get(route,false)).status,403,'Anonymous asset access must stay forbidden');
            const response = await get(route); assert.equal(response.status,200,route);
            const type = path.extname(name)==='.png' ? 'image/png' : path.extname(name)==='.gltf' ? 'model/gltf+json' : 'application/octet-stream';
            assert.equal(response.headers.get('content-type'),type,route);
            const bytes = Buffer.from(await response.arrayBuffer());
            const diskFile = state.iconFiles?.[name] || path.join(state.assetDir,name);
            assert.deepEqual(bytes,await fs.readFile(diskFile),`${name}: served content differs from its real export`);
            assert.ok(bytes.length,`${name}: empty asset`);
            result.resources.push({route,bytes:bytes.length,sha256:digest(bytes),type});
            return bytes;
          })();
          requests.set(name,request); return request;
        };
        for (const item of state.character.equipment) {
          assert.equal(item.icon,`icon-${item.itemId}.png`,`${row.name}: missing icon for equipment slot ${item.slot}`);
          result.icons.push({slot:item.slot,itemId:item.itemId,...pngDimensions(await resource(item.icon),item.icon)});
        }
        for (const name of ['flowmage.gltf',...(state.character.attached || []).map(item => item.url)]) {
          const gltf = JSON.parse((await resource(name)).toString('utf8'));
          assert.equal(gltf.asset?.version,'2.0',`${name}: invalid glTF version`);
          assert.ok(gltf.meshes?.length,`${name}: no meshes`);
          if (name==='flowmage.gltf') assert.ok(gltf.animations?.some(animation => animation.channels?.length),`${name}: no character animation`);
          for (const buffer of gltf.buffers || []) assert.equal((await resource(buffer.uri)).length,buffer.byteLength,`${buffer.uri}: incorrect buffer size`);
          for (const image of gltf.images || []) pngDimensions(await resource(image.uri),image.uri);
          result.models.push({name,meshes:gltf.meshes.length,animations:gltf.animations?.length || 0,
            buffers:gltf.buffers?.length || 0,textures:gltf.images?.length || 0});
        }
      } catch (error) { result.errors.push(error.message); report.errors.push(`${row.name}: ${error.message}`); }
    }
    assert.ok(report.characters.some(character => character.icons.length>0),'The smoke must exercise actual equipped item PNGs');
    await verifyBrowser(origin,key,roster,states,selected,report,path.dirname(reportFile));
  } catch (error) { report.errors.push(error.message); }
  finally {
    if (server?.listening) { server.closeAllConnections(); await new Promise(resolve => server.close(resolve)); }
    report.completedAt = new Date().toISOString();
    report.passed = report.errors.length===0;
    await fs.mkdir(path.dirname(reportFile),{recursive:true});
    await fs.writeFile(reportFile,JSON.stringify(report,null,2)+'\n');
  }
  return report;
}

async function verifyBrowser(origin,key,roster,states,selected,report,outputDirectory) {
  await fs.mkdir(outputDirectory,{recursive:true});
  const {chromium} = require(process.env.PLAYWRIGHT_MODULE || path.join(process.env.USERPROFILE,
    '.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright'));
  const browser = await chromium.launch({channel:'msedge',headless:true,args:['--enable-unsafe-swiftshader']});
  const errors = [];
  try {
    const context = await browser.newContext({viewport:{width:1598,height:997},
      extraHTTPHeaders:{'X-Atlas-Armory-Key':key}});
    const page = await context.newPage();
    page.on('pageerror',error => errors.push(error.message));
    page.on('response',response => {
      if (response.status()>=400 && !response.url().endsWith('/favicon.ico')) errors.push(`${response.status()} ${new URL(response.url()).pathname}`);
    });
    await page.goto(origin+'/?lang=fr',{waitUntil:'domcontentloaded'});
    await page.waitForFunction(count => document.querySelectorAll('.character').length===count,roster.characters.length);
    for (const row of selected) {
      const result = report.characters.find(character => character.id===row.id);
      try {
        await page.locator(`.character[data-id="${row.id}"]`).click();
        const active = await (await page.locator('#character-view').elementHandle()).contentFrame();
        await active.waitForFunction(id => window.armory?.ready && window.armory.data.characterId===id,row.id,{timeout:60000});
        await active.waitForFunction(() => [...document.querySelectorAll('button.slot img')].every(image => image.complete && image.naturalWidth>1));
        const rendered = await active.evaluate(() => {
          let meshes = 0,vertices = 0;
          window.armory.root.traverseVisible(mesh => {
            if (mesh.isMesh) { meshes++; vertices+=mesh.geometry.attributes.position?.count || 0; }
          });
          return {id:window.armory.data.characterId,name:window.armory.data.name,classId:window.armory.data.classId,
            raceId:window.armory.data.raceId,meshes,vertices,frames:window.armory.frames,
            modelVisible:document.getElementById('loading').hidden,
            slots:document.querySelectorAll('button.slot').length,
            icons:[...document.querySelectorAll('button.slot img')].map(image => ({
              route:new URL(image.src).pathname,width:image.naturalWidth,height:image.naturalHeight})),
            statisticsSource:window.armory.data.statistics?.source || null,
            statistics:[...document.querySelectorAll('.character-stat')].map(row => ({
              key:row.dataset.stat,label:row.querySelector('dt').textContent,value:row.querySelector('dd').textContent}))};
        });
        assert.equal(rendered.id,row.id); assert.equal(rendered.name,row.name);
        assert.equal(rendered.classId,row.classId); assert.equal(rendered.raceId,row.race);
        assert.ok(rendered.modelVisible && rendered.meshes>0 && rendered.vertices>0,'The character model must actually render');
        assert.equal(rendered.slots,states.get(row.id).character.equipment.length);
        assert.equal(rendered.icons.length,rendered.slots,'Every equipped item must decode its real PNG');
        assert.ok(rendered.icons.every(icon => icon.route.startsWith(`/characters/${row.id}/snapshots/`)),
          'The browser must not reuse another character snapshot');
        const before = await active.evaluate(() => window.armory.animatedTime);
        await active.waitForFunction(before => window.armory.animatedTime>before,before);
        result.browser = {...rendered,animated:true,viewport:{width:1598,height:997},screenshot:`friend-${row.id}.png`};
        await page.screenshot({path:path.join(outputDirectory,result.browser.screenshot)});
      } catch (error) {
        result.errors.push(error.message); report.errors.push(`${row.name} browser: ${error.message}`);
        await page.screenshot({path:path.join(outputDirectory,`friend-${row.id}-failed.png`)});
      }
    }
    report.browserErrors = errors;
    assert.deepEqual(errors,[],'The real character views must load without script or HTTP errors');
  } finally { await browser.close(); }
}

if (require.main===module) {
  const [directory,output,characterId,...extra] = process.argv.slice(2);
  if (!directory || !output || extra.length || characterId && !/^[1-9][0-9]{0,9}$/.test(characterId)) {
    console.error('Usage: node verify-real-friend-assets.cjs <account-cache-directory> <report.json> [character-id]');
    process.exitCode = 2;
  } else verify(path.resolve(directory),path.resolve(output),characterId).then(report => {
    console.log(`${report.passed?'PASS':'FAIL'}: actual cached character assets over authenticated loopback HTTP; ${report.characters.length} character(s).`);
    for (const error of report.errors) console.error(error);
    process.exitCode = report.passed ? 0 : 1;
  }).catch(error => { console.error(error.message); process.exitCode = 1; });
}

module.exports = {verify};
